import assert from 'node:assert/strict';
import {createRequire} from 'node:module';
import {readFileSync,writeFileSync,mkdirSync} from 'node:fs';
import {renderEdgeResultDraft} from '../../docs/results/result-generation-edge-renderer-20261127-CANDIDATE-DO-NOT-DEPLOY.mjs';
const require=createRequire(import.meta.url);
const PDFDocument=require('/tmp/ksol-pdf-deps/node_modules/pdfkit');
const [latin,hindi]=process.argv.slice(2);
const deps={PDFDocument,latinFont:readFileSync(latin),hindiFont:readFileSync(hindi)};
const snapshot={attemptId:'00000000-0000-0000-0000-000000000010',studentName:'काल्पनिक विद्यार्थी (Synthetic Student)',rollNo:'SYN-01',classLevel:'10',schoolName:'नमूना विद्यालय Public School',testTitle:{hi:'सामाजिक विज्ञान Social Science'},subject:'सामाजिक विज्ञान',score:8,totalMarks:10,percentage:80,submittedAt:'2026-01-01T00:00:00Z'};
const design={theme:'modern',version:1,options:{brandTitle:'KRISHAN SIR ONLINE LEARNING',tagline:'शिक्षा और ज्ञान',footerNote:'Synthetic data only'}};
const result=await renderEdgeResultDraft(snapshot,design,deps);
assert.match(result.sha256,/^[a-f0-9]{64}$/);
assert.equal(result.templateVersion,1);
assert.equal(result.attemptId,snapshot.attemptId);
mkdirSync('/tmp/ksol-result-render',{recursive:true});
writeFileSync('/tmp/ksol-result-render/portable.pdf',result.bytes);
console.log('PORTABLE_PDF_SYNTHETIC_RENDER_MS='+Math.round(result.elapsedMs));
await assert.rejects(renderEdgeResultDraft({...snapshot,studentName:'A'.repeat(240)},design,deps));
await assert.rejects(renderEdgeResultDraft({...snapshot,percentage:101},design,deps));
console.log('PORTABLE_PDF_RENDERER_SYNTHETIC_ASSERTIONS_PASSED');
